// Só leitura (decisão 114 do Jorge, 01/11/2026). A mesma chamada do guardião do Google.
const q = $('Manual').first().json.query || {};
const data = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? s : '';
const desde = data(q.desde) || '2026-10-01', ate = data(q.ate) || '2026-10-31';
// ?grupos=Nome 1,Nome 2 troca os grupos lidos (01/11/2026: conferir se os grupos de unidade têm a palavra antes da negativa B)
const GRUPOS = (q.grupos ? String(q.grupos).split(',').map(s => s.trim()).filter(Boolean).slice(0, 10) : ["TESTE DE PALAVRAS", "Asa Sul", "Institucional + Concorrentes"]);
const CONTA = '5066798424', token = $('Google · renova o acesso').first().json.access_token;
if (!token) throw new Error('sem acesso (token) do Google Ads');
const busca = async q => { let out = [], pt; do { const r = await this.helpers.httpRequest({ method: 'POST', url: `https://googleads.googleapis.com/v25/customers/${CONTA}/googleAds:search`, headers: { Authorization: 'Bearer ' + token }, body: { query: q, ...(pt ? { pageToken: pt } : {}) }, json: true, timeout: 60000 }); out = out.concat(r.results || []); pt = r.nextPageToken; } while (pt); return out; };
const lista = GRUPOS.map(g => `'${g.replace(/'/g, "\\'")}'`).join(', ');
const per = `segments.date BETWEEN '${desde}' AND '${ate}'`;
const termos = await busca(`SELECT search_term_view.search_term, search_term_view.status, ad_group.name, campaign.name, metrics.cost_micros, metrics.clicks, metrics.impressions, metrics.conversions FROM search_term_view WHERE ${per} AND ad_group.name IN (${lista})`);
const palavras = await busca(`SELECT ad_group.name, ad_group_criterion.keyword.text, ad_group_criterion.keyword.match_type, ad_group_criterion.status, metrics.cost_micros, metrics.clicks, metrics.conversions FROM keyword_view WHERE ${per} AND ad_group.name IN (${lista}) AND ad_group_criterion.negative = FALSE`);
// (05/11/2026: sem o filtro, as negativas do grupo vinham como palavra ENABLED, com gasto zero)
const negCamp = await busca(`SELECT campaign.name, campaign_criterion.keyword.text, campaign_criterion.keyword.match_type FROM campaign_criterion WHERE campaign_criterion.negative = TRUE AND campaign_criterion.type = 'KEYWORD' AND campaign.status != 'REMOVED'`);
const negGrupo = await busca(`SELECT ad_group.name, ad_group_criterion.keyword.text, ad_group_criterion.keyword.match_type FROM ad_group_criterion WHERE ad_group_criterion.negative = TRUE AND ad_group_criterion.type = 'KEYWORD' AND ad_group.name IN (${lista})`);
let listas = []; try { listas = await busca(`SELECT shared_set.name, shared_criterion.keyword.text, shared_criterion.keyword.match_type FROM shared_criterion WHERE shared_set.type = 'NEGATIVE_KEYWORDS'`); } catch (e) {}
const r2 = v => Math.round(Number(v || 0) / 1e4) / 100;
const grupos = {};
for (const g of GRUPOS) grupos[g] = { gasto: 0, cliques: 0, contatos: 0, termos: [], palavras: [], negativas_do_grupo: [] };
for (const x of termos) { const g = grupos[x.adGroup.name]; if (!g) continue; const t = { termo: x.searchTermView.searchTerm, situacao: x.searchTermView.status, gasto: r2(x.metrics.costMicros), cliques: Number(x.metrics.clicks || 0), impressoes: Number(x.metrics.impressions || 0), contatos: Math.round(Number(x.metrics.conversions || 0) * 10) / 10 };
  g.termos.push(t); g.gasto += t.gasto; g.cliques += t.cliques; g.contatos += t.contatos; }
for (const x of palavras) { const g = grupos[x.adGroup.name]; if (g) g.palavras.push({ palavra: x.adGroupCriterion.keyword.text, tipo: x.adGroupCriterion.keyword.matchType, situacao: x.adGroupCriterion.status, gasto: r2(x.metrics.costMicros), cliques: Number(x.metrics.clicks || 0), contatos: Math.round(Number(x.metrics.conversions || 0) * 10) / 10 }); }
for (const x of negGrupo) { const g = grupos[x.adGroup.name]; if (g) g.negativas_do_grupo.push(x.adGroupCriterion.keyword.text + ' (' + x.adGroupCriterion.keyword.matchType + ')'); }
for (const g of Object.values(grupos)) { g.gasto = Math.round(g.gasto * 100) / 100; g.termos.sort((a, b) => b.gasto - a.gasto); g.palavras.sort((a, b) => b.gasto - a.gasto); }
return [{ json: { periodo: { desde, ate }, grupos, negativas_da_campanha: negCamp.map(x => ({ campanha: x.campaign.name, termo: x.campaignCriterion.keyword.text, tipo: x.campaignCriterion.keyword.matchType })),
  listas_de_negativas: listas.map(x => ({ lista: x.sharedSet.name, termo: x.sharedCriterion.keyword.text, tipo: x.sharedCriterion.keyword.matchType })) } }];
